package io.github.jesterportfolio.hearth.features;

import io.github.jesterportfolio.hearth.exploration.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.quest.*;
import io.github.jesterportfolio.hearth.session.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.MapMeta;
import org.bukkit.map.*;
import org.bukkit.persistence.PersistentDataType;

/** 소유자의 발견 영역·현재 접근만 문맥별로 렌더링합니다. 미로드 청크를 생성하지 않습니다. */
public final class PaperCartography implements AutoCloseable {
    private final JavaPluginRef keys;private final PaperSessionAdapter players;private final PlayerSessions sessions;private final InventoryStore store;private final PaperInventoryCodec codec;private final QuestJournal journal;private final ExplorationContent content;private final QuestCatalog catalog;private record Projection(PlayerSessions.Session session,QuestJournal.View view){}private final Map<Player,Projection> views=new IdentityHashMap<>();private final Map<Integer,Byte> colors=new HashMap<>();private final Map<Integer,MapRenderer> attached=new HashMap<>();private boolean closed;private final Executor owner;
    private record JavaPluginRef(NamespacedKey owner,NamespacedKey run,NamespacedKey round){}
    public PaperCartography(org.bukkit.plugin.java.JavaPlugin plugin,PaperSessionAdapter players,PlayerSessions sessions,InventoryStore store,PaperInventoryCodec codec,QuestJournal journal,ExplorationContent content,QuestCatalog catalog,Executor owner){keys=new JavaPluginRef(new NamespacedKey(plugin,"map_owner"),new NamespacedKey(plugin,"map_run"),new NamespacedKey(plugin,"map_round"));this.players=players;this.sessions=sessions;this.store=store;this.codec=codec;this.journal=journal;this.content=content;this.catalog=catalog;this.owner=owner;}
    public void present(Player p,QuestJournal.View view){var session=players.prepared(p);if(session==null)return;views.put(p,new Projection(session,view));for(var item:p.getInventory().getStorageContents())if(owned(item,p,session)&&item.getItemMeta() instanceof MapMeta meta&&meta.hasMapView())attach(meta.getMapView(),p.getUniqueId(),session.context().storyRunId(),Boolean.TRUE.equals(meta.getPersistentDataContainer().get(keys.round,PersistentDataType.BOOLEAN)));}
    private boolean owned(ItemStack item,Player p,PlayerSessions.Session session){if(item==null||item.getType()!=Material.FILLED_MAP)return false;var data=item.getItemMeta().getPersistentDataContainer();return p.getUniqueId().toString().equals(data.get(keys.owner,PersistentDataType.STRING))&&session.context().storyRunId().toString().equals(data.get(keys.run,PersistentDataType.STRING));}
    public boolean command(Player p,String line){if(!line.equals("/hearthmap")&&!line.equals("/hearthmap round"))return false;give(p,line.endsWith(" round"));return true;}
    public void give(Player p,boolean round){var session=players.current(p);if(session==null)return;var data=views.get(p);var view=data==null?null:data.view();if(view==null||data.session()!=session){p.sendMessage(Component.text("현재 공개 지도 정보를 먼저 조회하세요."));return;}try{journal.requireView(session.context(),view);}catch(RuntimeException stale){p.sendMessage(Component.text("현재 지도 정보를 다시 조회하세요."));return;}
        for(var item:p.getInventory().getStorageContents())if(owned(item,p,session)&&Objects.equals(item.getItemMeta().getPersistentDataContainer().get(keys.round,PersistentDataType.BOOLEAN),round)){p.sendMessage(Component.text("본인의 지도 아이템을 손에 들어 확인하세요. 발견한 장소만 표시합니다."));return;}
        sessions.inventoryTransaction(session,before->{var slots=codec.decode(before.payload());int free=-1;for(int i=0;i<36;i++)if(slots[i]==null||slots[i].isEmpty()){free=i;break;}if(free<0)return CompletableFuture.failedFuture(new IllegalStateException("MAP_INVENTORY_FULL"));var map=Bukkit.createMap(p.getWorld());map.setLocked(true);map.setTrackingPosition(false);map.setUnlimitedTracking(false);attach(map,p.getUniqueId(),session.context().storyRunId(),round);var item=new ItemStack(Material.FILLED_MAP);var meta=(MapMeta)item.getItemMeta();meta.setMapView(map);meta.displayName(Component.text(round?"개인 원형 미니맵":"개인 발견 지형 지도"));meta.getPersistentDataContainer().set(keys.owner,PersistentDataType.STRING,p.getUniqueId().toString());meta.getPersistentDataContainer().set(keys.run,PersistentDataType.STRING,session.context().storyRunId().toString());meta.getPersistentDataContainer().set(keys.round,PersistentDataType.BOOLEAN,round);item.setItemMeta(meta);slots[free]=item;return store.saveInventory(session.context(),before.revision(),codec.encode(slots));}).whenCompleteAsync((v,error)->{if(players.prepared(p)==session)p.sendMessage(Component.text(error==null?"개인 지도를 저장했습니다. 손에 들거나 보조 손으로 옮겨 확인하세요.":"지도 저장을 확인하지 못했습니다. 원본 저장 상태를 보존합니다."));},owner);
    }
    public static List<Cartography.Zone> zones(ExplorationContent content,ExplorationView view){return view.places().stream().filter(p->p.discovered()||content.places().containsKey(p.key())&&content.places().get(p.key()).visibility()==ExplorationContent.Visibility.PUBLIC).map(p->content.places().get(p.key())).filter(Objects::nonNull).filter(p->!p.location().kind().equals("NONE")).map(p->new Cartography.Zone(p.id(),(int)Math.ceil(p.bounds().minX()),(int)Math.floor(p.bounds().maxX()),(int)Math.ceil(p.bounds().minZ()),(int)Math.floor(p.bounds().maxZ()))).toList();}
    public byte[] raster(World world,int x,int z,boolean round,ExplorationView view){var zones=zones(content,view);return Cartography.render(x,z,1,round,zones,new Cartography.Terrain(){public boolean loaded(int x,int z){return world.isChunkLoaded(x>>4,z>>4);}public byte color(int x,int z){int y=world.getHighestBlockYAt(x,z);boolean known=content.places().values().stream().anyMatch(place->!place.location().kind().equals("NONE")&&view.place(place.id()).filter(p->p.discovered()||place.visibility()==ExplorationContent.Visibility.PUBLIC).isPresent()&&place.bounds().contains(x,y+1,z));if(!known)return 0;int rgb=world.getBlockAt(x,y,z).getBlockData().getMapColor().asRGB();return colors.computeIfAbsent(rgb,key->MapPalette.matchColor(new java.awt.Color(key)));}});}
    private void attach(MapView map,UUID player,UUID run,boolean round){if(attached.containsKey(map.getId()))return;map.setLocked(true);for(var renderer:List.copyOf(map.getRenderers()))map.removeRenderer(renderer);var renderer=new MapRenderer(true){final Map<MapCanvas,CanvasState> canvases=new WeakHashMap<>();public void render(MapView ignored,MapCanvas canvas,Player p){var cache=canvases.computeIfAbsent(canvas,c->new CanvasState());var s=players.prepared(p);var data=views.get(p);var view=data==null?null:data.view();boolean valid=!closed&&s!=null&&p.getUniqueId().equals(player)&&s.context().storyRunId().equals(run)&&view!=null&&data.session()==s&&(!round||view.journal().preferences().minimapEnabled());if(valid)try{journal.requireView(s.context(),view);}catch(RuntimeException stale){valid=false;}long now=System.nanoTime();if(valid&&now<cache.next)return;byte[] pixels=valid?raster(p.getWorld(),p.getLocation().getBlockX(),p.getLocation().getBlockZ(),round,view.exploration()):new byte[16384];if(cache.last==null||!Arrays.equals(cache.last,pixels)){for(int y=0;y<128;y++)for(int x=0;x<128;x++)canvas.setPixel(x,y,pixels[y*128+x]);cache.last=pixels;}var cursors=valid?markers(p,view,round):new MapCursorCollection();if(valid&&view.journal().preferences().playerMarker())cursors.addCursor(new MapCursor((byte)0,(byte)0,(byte)Math.floorMod((int)(p.getYaw()/22.5),16),MapCursor.Type.PLAYER,true));canvas.setCursors(cursors);cache.next=now+2_000_000_000L;}};attached.put(map.getId(),renderer);map.addRenderer(renderer);}
    private void cursor(MapCursorCollection cursors,Player p,double x,double z,boolean round,MapCursor.Type type,String label){int dx=(int)Math.round((x-p.getX())*2),dz=(int)Math.round((z-p.getZ())*2);if(Math.abs(dx)>126||Math.abs(dz)>126||round&&dx*dx+dz*dz>120*120||cursors.size()>=32)return;cursors.addCursor(new MapCursor((byte)dx,(byte)dz,(byte)0,type,true,Component.text(label)));}
    public MapCursorCollection markers(Player p,QuestJournal.View view,boolean round){var cursors=new MapCursorCollection();var prefs=view.journal().preferences();if(prefs.placeMarker())for(var known:view.exploration().places())if(known.discovered()){var place=content.places().get(known.key());if(place!=null&&!place.location().kind().equals("NONE"))cursor(cursors,p,(place.bounds().minX()+place.bounds().maxX())/2,(place.bounds().minZ()+place.bounds().maxZ())/2,round,MapCursor.Type.TARGET_POINT,known.name());}
        if(prefs.questMarker())for(String id:view.journal().tracked()){var saved=view.states().get(id);if(saved==null||saved.phase()!=QuestStore.Phase.ACTIVE||view.exploration().blockedQuests().contains(id))continue;var q=catalog.quest(id);var location=q.goal(saved).location();if(location!=null&&location.kind().equals("EXACT")&&location.point()!=null)cursor(cursors,p,location.point().x(),location.point().z(),round,MapCursor.Type.RED_X,q.title());}
        if(prefs.npcMarker())for(var contact:NpcGuidance.build(catalog,view,null,Set.of()).contacts()){var npc=catalog.npc(contact.npc());if(zones(content,view.exploration()).stream().anyMatch(zone->zone.contains((int)npc.x(),(int)npc.z())))cursor(cursors,p,npc.x(),npc.z(),round,MapCursor.Type.BLUE_MARKER,contact.name());}if(prefs.playerMarker())for(var other:Bukkit.getOnlinePlayers()){if(other==p||!other.getWorld().equals(p.getWorld()))continue;var theirs=players.prepared(other);var own=players.prepared(p);if(theirs!=null&&own!=null&&theirs.context().storyRunId().equals(own.context().storyRunId()))cursor(cursors,p,other.getX(),other.getZ(),round,MapCursor.Type.BANNER_GREEN,other.getName());}return cursors;}
    private static final class CanvasState{long next;byte[] last;}
    public void close(){closed=true;for(var entry:attached.entrySet()){var map=Bukkit.getMap(entry.getKey());if(map!=null)map.removeRenderer(entry.getValue());}attached.clear();views.clear();}
    public void forget(Player p){views.remove(p);}
}
